#!/usr/bin/env python3
"""Fail when an `import com.ethosprotocol.*` symbol has no Kotlin declaration.

Deleting a class, object, or function while another file still imports it only
shows up at compile time. This check catches the same mistake before Gradle runs.

Scope and limits:
- Only explicit imports under `com.ethosprotocol` are checked. Wildcard imports
  (`.*`) are skipped because they name no single symbol.
- Symbols generated by the build (`BuildConfig`, `R`) are skipped because they
  have no Kotlin source declaration.
- A symbol counts as declared when a `.kt` file under `android/` or `shared/`
  declares it with class/object/interface/typealias/fun/val/var. The check does
  not model overload resolution or shadowing.

Usage:
    python3 .github/scripts/check_kotlin_imports.py [--root <repo-root>]

Exit codes:
    0 - every checked import resolves to a declaration
    1 - one or more imports have no declaration
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

SOURCE_DIRS = ("android", "shared")
SKIP_DIR_NAMES = {"build", ".gradle", "node_modules"}
GENERATED_SEGMENTS = {"BuildConfig", "R"}

PACKAGE_RE = re.compile(r"^\s*package\s+([\w.]+)", re.MULTILINE)
IMPORT_RE = re.compile(
    r"^import\s+(com\.ethosprotocol(?:\.\w+)*)(\.\*)?(?:\s+as\s+\w+)?\s*$"
)
DECLARATION_RE = re.compile(
    r"^\s*(?:(?:public|private|internal|protected|data|sealed|open|abstract|enum|"
    r"annotation|inline|const|lateinit|override|suspend|tailrec|operator|infix|"
    r"external|value|inner|companion)\s+)*"
    r"(?:class|object|interface|typealias|fun|val|var)\s+"
    r"(?:<[^>]*>\s*)?(?:[A-Za-z_]\w*\.)?([A-Za-z_]\w*)",
    re.MULTILINE,
)


def kotlin_files(root: Path):
    for source_dir in SOURCE_DIRS:
        base = root / source_dir
        if not base.is_dir():
            continue
        for path in base.rglob("*.kt"):
            if any(part in SKIP_DIR_NAMES for part in path.relative_to(root).parts):
                continue
            yield path


def collect_declarations(files):
    """Return (declared (package, name) pairs, declared names)."""
    by_package: set[tuple[str, str]] = set()
    by_name: set[str] = set()
    for path in files:
        text = path.read_text(encoding="utf-8", errors="replace")
        match = PACKAGE_RE.search(text)
        package = match.group(1) if match else ""
        for decl in DECLARATION_RE.finditer(text):
            name = decl.group(1)
            by_package.add((package, name))
            by_name.add(name)
    return by_package, by_name


def find_import_problems(root: Path):
    files = list(kotlin_files(root))
    by_package, by_name = collect_declarations(files)
    declared_packages = {package for package, _ in by_package}

    problems = []
    for path in files:
        for line_no, line in enumerate(
            path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1
        ):
            match = IMPORT_RE.match(line.strip())
            if not match or match.group(2):
                continue
            fqn = match.group(1)
            segments = fqn.split(".")
            if GENERATED_SEGMENTS & set(segments):
                continue
            package, name = ".".join(segments[:-1]), segments[-1]
            if (package, name) in by_package:
                continue
            # Nested symbol, e.g. com.ethosprotocol.api.ApiClient.Nested: the
            # parent segment must itself be a declared type (not a package) and
            # the leaf must be declared somewhere in the sources.
            parent = package.rsplit(".", 1)[-1]
            if package not in declared_packages and parent in by_name and name in by_name:
                continue
            rel = path.relative_to(root)
            problems.append(f"{rel}:{line_no}: '{fqn}' has no Kotlin declaration")
    return problems


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parents[2],
        help="repository root (default: the checkout containing this script)",
    )
    args = parser.parse_args(argv)

    problems = find_import_problems(args.root.resolve())
    for problem in problems:
        print(f"::error::{problem}")
    if problems:
        print(f"{len(problems)} import(s) reference a symbol with no declaration.")
        return 1
    print("OK: every com.ethosprotocol import resolves to a declaration.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
